What does this function return for the call shown? Work it out step by
step, then end your reply with the number.

def f(items):
    seen, order = {}, []
    for name, n in items:
        if name in seen:
            seen[name] += n
        else:
            seen[name] = n
            order.append(name)
        if seen[name] > 5:
            seen[name] = 0
            order.remove(name)
            order.insert(0, name)
    return sum(seen[k] * (i + 1) for i, k in enumerate(order))

